    assert!(offered, "A2 may stack it onto a unit");
    assert_eq!(duos_passes(&state, A1), vec![id]);
}

#[test]
fn b28_a_flying_unit_is_passed_into_a_teammates_backrow_past_its_full_unit_row() {
