    set_mana(&mut state, A1, DUOS_PASS_COST);
    set_hand(&mut state, A2, &[]);
    set_mana(&mut state, A2, cost(def_id));
    fill_units(&mut state, A2, ONE_DROP);
    assert!(
        !can_play(&state.duels[0], PlayerId::P1, &id),
        "A1 cannot afford it"
